  "dataModelSchema": {
    "data": {
      "todo": {
        "title": {
          "type": "string",
          "description": "待办清单标题",
          "sampleValue": "今日待办"
        },
        "summaryText": {
          "type": "string",
          "description": "待办数量和完成情况摘要",
          "sampleValue": "3 项任务 · 1 项已完成"
        },
        "updatedText": {
          "type": "string",
          "description": "待办清单最近同步或更新时间",
          "sampleValue": "刚刚更新"
        },
        "items": [
          {
            "title": {
              "type": "string",
              "description": "第一条待办任务标题",
              "sampleValue": "补交报销单"
            },
            "statusText": {
              "type": "string",
              "description": "第一条待办任务完成状态",
              "sampleValue": "待完成"
            },
            "done": {
              "type": "boolean",
              "description": "第一条待办任务是否已完成",
              "sampleValue": false
            }
          },
          {
            "title": {
              "type": "string",
              "description": "第二条待办任务标题",
              "sampleValue": "确认会议纪要"
            },
            "statusText": {
              "type": "string",
              "description": "第二条待办任务完成状态",
              "sampleValue": "已完成"
            },
            "done": {
              "type": "boolean",
              "description": "第二条待办任务是否已完成",
              "sampleValue": true
            }
          },
          {
            "title": {
              "type": "string",
              "description": "第三条待办任务标题",
              "sampleValue": "给家里回电"
            },
            "statusText": {
              "type": "string",
              "description": "第三条待办任务完成状态",
              "sampleValue": "待完成"
            },
            "done": {
              "type": "boolean",
              "description": "第三条待办任务是否已完成",
              "sampleValue": false
            }
          }
        ]
      }
    }
  },
  "assetCandidates": []
}

